import java.util.*;
import java.io.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;

    // Reads the next whitespace-separated token from stdin
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) st = new StringTokenizer(br.readLine());
        return st.nextToken();
    }

    static int nextInt() throws IOException { return Integer.parseInt(next()); }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        HashMap<String, List<String>> groups = new HashMap<>();
        for (int i = 0; i < n; i++) {
            String w = next();
            char[] c = w.toCharArray();
            Arrays.sort(c);                       // sorted letters = family key
            String key = new String(c);
            groups.computeIfAbsent(key, k -> new ArrayList<>()).add(w);
        }
        List<List<String>> list = new ArrayList<>(groups.values());
        for (List<String> g : list) Collections.sort(g);
        // groups share no words, so their first words decide the order
        Collections.sort(list, (x, y) -> x.get(0).compareTo(y.get(0)));
        StringBuilder sb = new StringBuilder();
        for (List<String> g : list) sb.append(String.join(" ", g)).append('\n');
        System.out.print(sb);
    }
}

